visual('higiene_ocupacional',MED,'arredondamento_intervalo','Leitura com arredondamento declarado','Display5,0 unidades. Regra: valores em[4,95;5,05) são exibidos5,0.',table(['Display','Regra'],[['5,0','[4,95;5,05)']]),'Qual afirmação é sustentada sem confundir indicação e valor anterior ao arredondamento?', ['O valor está no intervalo declarado; não se conhece exatamente5,0.','O valor é necessariamente5,0000.','A largura do intervalo é1,0 unidade.','O intervalo comprova ausência de erro sistemático.','Qualquer valor até5,5 produz essa indicação.'],'A regra informa uma classe de valores com largura0,10. Resolução de exibição não comprova exatidão ou ausência de viés.','roundInterval',[4.95,5.05],.1)
visual('higiene_ocupacional',HIGH,'tempo_morto_contagem','Correção didática de tempo morto','Contagem observada1000s⁻¹; tempo mortoτ0,0002s. Modelo não paralisável Nreal=Nobs/(1−Nobsτ).',table(['Parâmetro','Valor'],[['N observado','1000 s⁻¹'],['τ','0,0002 s'],['Modelo','Nreal=Nobs/(1−Nobsτ)']]),'Qual taxa corrigida e aumento relativo sobre a observada?', ['1250s⁻¹ e25%.','800s⁻¹ e−20%.','1200s⁻¹ e20%.','1000s⁻¹ e0%.','5000s⁻¹ e400%.'],'Denominador1−0,2=0,8, taxa1250; aumento250/1000=25%. É um modelo instrumental, não taxa de dose nem limite legal.','deadTime',[1000,.0002],[1250,.25])
visual('higiene_ocupacional',VERY,'filtro_dinamico_area_e_pico','Resposta de um detector a pulso','Entrada C=10 por2min e depois0; τyprimeiro=C−y, τ=1min, y0=0, tempo emmin. y(2)=10(1−e⁻²); e⁻²=0,1353; y termina em0.',table(['Grandeza','Definição'],[['Entrada','10 durante 2 min; depois 0'],['Resposta','τdy/dt=C−y; τ=1min; y(0)=0'],['Constante','e⁻²=0,1353']]),'No modelo, qual pico aproximado de y e área total da resposta de0 até infinito? Use integrar a equação e os estados inicial/final.', ['8,647 e20 unidades·min.','10 e20, pois todo pico é preservado.','8,647 e17,294, pois a resposta acaba no minuto2.','1,353 e20.','8,647 e10.'],'Pico no fim do pulso:10×0,8647=8,647. Integrando τyprimeiro=C−y com extremos zero, integral y=integral C=20. A cauda mantém área, mas não restaura o pico perdido.','filteredPulse',[10,2,.1353],[8.647,20])
