visual('gestao_sms',VERY,'portfolio_com_intersecoes','Projetos e falha de orçamento','Benefícios A5,B8,C6. Probabilidades de sobrecusto:A0,10;B0,20;C0,15;AB0,06;AC0,04;BC0,05;ABC0,03. Critério: P(algum)≤0,32. Maximizar benefício somado.',table(['Objeto','Probabilidade / benefício'],[['A / B / C','0,10 / 0,20 / 0,15; b=5/8/6'],['AB / AC / BC','0,06 / 0,04 / 0,05'],['ABC','0,03'],['Máximo interno','0,32']]),'Qual probabilidade da união dos três e qual conjunto de maior benefício admissível?', ['0,33; B+C, benefício14.','0,45; A+B+C, benefício19.','0,30; A+B+C, benefício19.','0,33; A+B, benefício13.','0,21; A+C, benefício11.'],'União0,10+0,20+0,15−0,06−0,04−0,05+0,03=0,33, inadmissível. ParesAB0,24,AC0,21,BC0,30 atendem; BC dá maior benefício14.','portfolioUnion',[.1,.2,.15,.06,.04,.05,.03],[.33,'BC',14])
