def nodes(data,edges,notes):
 s=''
 for a,b,label in edges:
  x,y,_=data[a];X,Y,_=data[b];sx,sy=x+72.5,y+27.5;tx,ty=X+72.5,Y+27.5;dx,dy=tx-sx,ty-sy;k=1/max(abs(dx)/72.5,abs(dy)/27.5);edge=line(sx+dx*k,sy+dy*k,tx-dx*k,ty-dy*k);edge=edge.replace('/>',' marker-end="url(#arrow)"/>') if len(Q)+1 not in (84,88) else edge;s+=edge+t((sx+tx)/2,(sy+ty)/2-8,label,17)
 for x,y,label in data.values():s+=box(x,y,145,55,label)
 for i,n in enumerate(notes):s+=t(35,455+32*i,n,19)
 return s
